//! The static UI assets generated by `tools/extract_ui_assets.py` (CSS, JS,
//! f-string templates, constants, the favicon), embedded in the binary. The index
//! of files is generated by `build.rs`, so adding an asset is just adding a file
//! under `crates/server/assets/`.

include!(concat!(env!("OUT_DIR"), "/embedded_assets.rs"));

/// The bytes of `assets/<path>`.
pub fn get(path: &str) -> Option<&'static [u8]> {
    EMBEDDED.iter().find(|(p, _)| *p == path).map(|(_, b)| *b)
}

/// `assets/<path>` as UTF-8 text.
pub fn text(path: &str) -> Option<&'static str> {
    get(path).and_then(|b| std::str::from_utf8(b).ok())
}

/// The first 8 hex digits of the SHA-256 over every asset under `prefix` (names and
/// bytes): one cache-buster for a set of files that import each other.
pub fn version_of(prefix: &str) -> String {
    // The Office page asks on every render and its set (three.js included) is large;
    // embedded assets never change, so hash that prefix once.
    if prefix == "office/" {
        static OFFICE: std::sync::OnceLock<String> = std::sync::OnceLock::new();
        return OFFICE.get_or_init(|| hash_prefix(prefix)).clone();
    }
    hash_prefix(prefix)
}

fn hash_prefix(prefix: &str) -> String {
    let mut all = Vec::new();
    let mut files: Vec<_> = EMBEDDED
        .iter()
        .filter(|(p, _)| p.starts_with(prefix))
        .collect();
    files.sort_by_key(|(p, _)| *p);
    for (path, bytes) in files {
        all.extend_from_slice(path.as_bytes());
        all.push(0);
        all.extend_from_slice(bytes);
    }
    loopx_core::sha256::hex(&loopx_core::sha256::sha256(&all))[..8].to_string()
}

pub fn favicon() -> &'static [u8] {
    get("favicon.ico").unwrap_or(&[])
}

/// `_favicon_version()`: the first 8 hex digits of the favicon's SHA-256, the
/// cache-buster on the `<link rel="icon">`.
pub fn favicon_version() -> String {
    let icon = favicon();
    if icon.is_empty() {
        return "0".to_string();
    }
    loopx_core::sha256::hex(&loopx_core::sha256::sha256(icon))[..8].to_string()
}
